.project-block {
  margin-left: 1.5rem;
  width: 97.5%;  
}

/* Two-column layout */
.text-columns {
  display: flex;
  gap: 20px; /* space between columns */
  margin-bottom: 20px;
  height: auto; /* adjust for spacer */
}

.column-1 {
  flex: 0 0 33%;
  display: flex;
  flex-direction: column;
  justify-content: space-between; /* pushes info to bottom */
}

.column-2 {
  flex: 0 0 66%;
}

/* Title styling */
.column-title {
  font-size: 1.5em; /* bigger title */
  font-weight: bold;
}

/* Smaller, more compact text */
.column-text {
  font-size: 1.05rem;
  line-height: 1.3em;

}

.video-info {
  font-size: 1.05rem;
  line-height: 1.5rem;
  color: #fff;

}

.video-info strong {
    font-size: 1.05rem;   /* ← this fixes the size mismatch */
    font-weight: 600;     /* keep emphasis */
}

/* Vimeo video container */
.video-container {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%; /* 16:9 ratio */
  height: 0;
  overflow: hidden;
}

.video-container iframe {
  position: absolute;
  top: 1rem;
  left: 0;
  width: 100%;
  height: 100%;
}
gallery-freeform {
  display: flex;          /* align items in a row */
  flex-wrap: wrap;        /* allow wrapping to new lines */
  gap: 2rem;              /* consistent gutter between items */
  margin-top: 40px;
}

gallery-freeform media-item {
  flex: 1 1(25% - 1rem); /* each item takes ~25% of row minus gutter */
  max-width: (55% - 1rem); 
  margin: 0;                  /* gap handles spacing */
  box-sizing: border-box;     
  aspect-ratio: 1/1;          /* force square items; optional */
  object-fit: cover;           /* fill the square without distortion */
}

  .view-full-project {
    margin-top: 2rem;
    position: relative;
    display: inline-block;
    color: #d1d1d1;
    text-decoration: none;
    margin-bottom: -1.2rem; 
    transition: color 0.3s ease;
}

.view-full-project::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 3px;
    width: 100%;
    height: 1.5px;
    background: currentColor;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.3s ease;
}

.view-full-project:hover {
    color: white;
}

.view-full-project:hover::after {
    transform: scaleX(1);
}

